package cn.zhuatech.documentai.controller; import cn.zhuatech.documentai.common.ApiResponse; import cn.zhuatech.documentai.dto.DocumentAiDto.*; import cn.zhuatech.documentai.service.DocumentAiService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasAnyRole('DOMAIN_OPERATOR','QUALITY','ADMIN')") public class OperationsAdminController {private final DocumentAiService service;public OperationsAdminController(DocumentAiService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.adminDashboard());}@GetMapping("/work-orders") public ApiResponse<List<WorkRecordView>> orders(){return ApiResponse.ok(service.workRecords());}}
